=== examples/mm6925a1.json ===
{
 "id": "mm6925a1",
 "reader": {
  "model": "claude-opus-5-5",
  "reader_id": "example",
  "role": "example"
 },
 "data_focus": {
  "v": "yes",
  "ev": []
 },
 "outcome_types": [
  {
   "v": "binary/categorical",
   "ev": [
    {
     "loc": "text",
     "q": "Hospitalization was reported by a substantially higher percentage of pregnant women (31.5%) than nonpregnant women (5.8%)"
    }
   ]
  }
 ],
 "analytic_depth": [
  {
   "v": "summary",
   "ev": [
    {
     "loc": "text",
     "q": "Data on pregnancy status were available for 91,412 (28.0%) of these women; 8,207 (9.0%) were pregnant"
    }
   ]
  },
  {
   "v": "comparison",
   "ev": [
    {
     "loc": "text",
     "q": "Pregnant women were admitted more frequently to the ICU (1.5%) than were nonpregnant women (0.9%)."
    }
   ]
  },
  {
   "v": "stratified/adjusted",
   "ev": [
    {
     "loc": "text",
     "q": "Risk ratios were adjusted for age (as a continuous variable), presence of underlying chronic conditions (yes/no), and race/ethnicity."
    },
    {
     "loc": "text",
     "q": "When stratified by age, all outcomes (hospitalization, ICU admission, receipt of mechanical ventilation, and death) were more frequently reported among women aged 35–44 years"
    }
   ]
  }
 ],
 "procedures": [
  {
   "name": "modified Poisson regression",
   "class": "regression",
   "regression_family": "loglinear",
   "inferred_from": "'modified Poisson regression' giving crude and adjusted risk ratios → loglinear; 'modified' means robust variance",
   "role": "primary",
   "ev": [
    {
     "loc": "text",
     "q": "Crude and adjusted risk ratios and 95% CIs for outcomes were calculated using modified Poisson regression."
    }
   ]
  },
  {
   "name": "missing outcomes coded as not having occurred",
   "class": "other",
   "regression_family": null,
   "inferred_from": "a data-handling rule applied to every outcome denominator",
   "role": "ancillary",
   "ev": [
    {
     "loc": "text",
     "q": "Outcomes with missing data were assumed not to have occurred"
    }
   ]
  }
 ],
 "comparison": {
  "framework": "pair",
  "scale": "relative",
  "referent": "nonpregnant women",
  "across": [
   "pregnancy status",
   "age group",
   "race/ethnicity"
  ],
  "ev": [
   {
    "loc": "table 2",
    "q": "Nonpregnant women are the referent group."
   },
   {
    "loc": "table 2",
    "q": "by pregnancy status, age group, and race/ethnicity, and relative risk for these outcomes comparing pregnant women to nonpregnant women"
   }
  ]
 },
 "inference": {
  "v": "CIs",
  "method_stated": true,
  "ev": [
   {
    "loc": "text",
    "q": "Crude and adjusted risk ratios and 95% CIs for outcomes were calculated using modified Poisson regression."
   }
  ]
 },
 "primary_measures": [
  {
   "v": "percentage",
   "ev": [
    {
     "loc": "text",
     "q": "Hospitalization was reported by a substantially higher percentage of pregnant women (31.5%) than nonpregnant women (5.8%)"
    }
   ]
  },
  {
   "v": "crude risk ratio",
   "ev": [
    {
     "loc": "table 2",
     "q": "Crude risk ratio (95% CI)"
    }
   ]
  },
  {
   "v": "aRR",
   "ev": [
    {
     "loc": "text",
     "q": "(aRR = 1.5, 95% confidence interval [CI] = 1.2–1.8)"
    }
   ]
  }
 ],
 "regression_fields": {
  "nonindependence_approach": {
   "v": "clustered or robust SE",
   "ev": [
    {
     "loc": "text",
     "q": "were calculated using modified Poisson regression."
    }
   ]
  },
  "unadjusted_results": {
   "v": true,
   "ev": [
    {
     "loc": "text",
     "q": "Crude and adjusted risk ratios and 95% CIs for outcomes were calculated using modified Poisson regression."
    }
   ]
  },
  "adjusted_results": {
   "v": true,
   "ev": [
    {
     "loc": "table 2",
     "q": "Adjusted for age as a continuous variable, dichotomous yes/no variable for presence of underlying conditions, and categorical race/ethnicity variable."
    }
   ]
  },
  "confounders": {
   "v": "age (as a continuous variable), presence of underlying chronic conditions (yes/no), and race/ethnicity",
   "ev": [
    {
     "loc": "text",
     "q": "Risk ratios were adjusted for age (as a continuous variable), presence of underlying chronic conditions (yes/no), and race/ethnicity."
    }
   ]
  },
  "interaction_modeled": {
   "v": false,
   "ev": []
  },
  "sensitivity_analysis": {
   "v": false,
   "ev": []
  }
 },
 "public_health_question": {
  "v": "Among women aged 15–44 years with laboratory-confirmed SARS-CoV-2 infection, do characteristics and the risk of severe outcomes differ by pregnancy status?",
  "ev": [
   {
    "loc": "text",
    "q": "data to assess the prevalence and severity of COVID-19 among pregnant U.S. women and determine whether signs and symptoms differ among pregnant and nonpregnant women"
   }
  ]
 },
 "conditions": [
  {
   "v": "COVID-19",
   "role": "population",
   "ev": [
    {
     "loc": "title",
     "q": "Characteristics of Women of Reproductive Age with Laboratory-Confirmed SARS-CoV-2 Infection by Pregnancy Status"
    }
   ]
  },
  {
   "v": "pregnancy",
   "role": "exposure",
   "ev": [
    {
     "loc": "summary",
     "q": "pregnancy was associated with hospitalization and increased risk for intensive care unit admission, and receipt of mechanical ventilation, but not with death."
    }
   ]
  }
 ],
 "study_design": [
  {
   "v": "surveillance/descriptive",
   "ev": [
    {
     "loc": "text",
     "q": "as part of COVID-19 surveillance, CDC received reports of 326,335 women of reproductive age (15–44 years)"
    }
   ]
  }
 ],
 "data_source_type": [
  {
   "v": "CDC surveillance system",
   "ev": [
    {
     "loc": "text",
     "q": "through the National Notifiable Diseases Surveillance System"
    }
   ]
  }
 ],
 "data_source_named": [
  {
   "v": "National Notifiable Diseases Surveillance System (NNDSS)",
   "ev": [
    {
     "loc": "text",
     "q": "through the National Notifiable Diseases Surveillance System"
    }
   ]
  },
  {
   "v": "CDC Human Infection with 2019 Novel Coronavirus Case Report Form",
   "ev": [
    {
     "loc": "table 1",
     "q": "CDC’s Human Infection with 2019 Novel Coronavirus Case Report Form"
    }
   ]
  }
 ],
 "setting": {
  "v": "US national",
  "ev": [
   {
    "loc": "text",
    "q": "among women aged 15–44 years from 50 states, the District of Columbia, and New York City."
   }
  ]
 },
 "vaccine_outcome_type": null,
 "equity": {
  "level": 2,
  "level_reason": "Hispanic and Black pregnant women are described as disproportionately affected, but the contrast is shares of cases set beside shares of 2019 births (46% vs 24%; 22% vs 15%) with no stated difference or ratio, so brief v4 caps it at 2.",
  "level_confidence": "medium",
  "level_alternative": {
   "level": 3,
   "reason": "Brief v3, and this example's earlier version, read the share-of-cases vs share-of-births contrast as a quantified disparity."
  },
  "dimensions": [
   {
    "v": "race/ethnicity",
    "role": "stratifier",
    "ev": [
     {
      "loc": "summary",
      "q": "Hispanic and non-Hispanic black pregnant women appear to be disproportionately affected by SARS-CoV-2 infection during pregnancy."
     },
     {
      "loc": "text",
      "q": "46% were Hispanic, 22% were black, and 23% were white; these proportions differ from those among women with reported race/ethnicity who gave birth in 2019"
     }
    ]
   },
   {
    "v": "race/ethnicity",
    "role": "covariate",
    "ev": [
     {
      "loc": "table 2",
      "q": "and categorical race/ethnicity variable."
     }
    ]
   },
   {
    "v": "age",
    "role": "stratifier",
    "ev": [
     {
      "loc": "text",
      "q": "When stratified by age, all outcomes (hospitalization, ICU admission, receipt of mechanical ventilation, and death) were more frequently reported among women aged 35–44 years"
     }
    ]
   },
   {
    "v": "age",
    "role": "covariate",
    "ev": [
     {
      "loc": "table 2",
      "q": "Adjusted for age as a continuous variable"
     }
    ]
   },
   {
    "v": "sex",
    "role": "population",
    "ev": [
     {
      "loc": "title",
      "q": "Characteristics of Women of Reproductive Age with Laboratory-Confirmed SARS-CoV-2 Infection by Pregnancy Status"
     }
    ]
   }
  ],
  "determinants_of_health": {
   "v": null,
   "ev": []
  },
  "equity_action": {
   "v": false,
   "ev": []
  },
  "equity_measurement": "Racial/ethnic shares of pregnant cases are compared with an external referent (women who gave birth in 2019); race/ethnicity is missing for 20% of pregnant women; American Indian/Alaska Native and Native Hawaiian/Other Pacific Islander are collapsed into other."
 },
 "groupwise": [
  {
   "across": [
    "race/ethnicity"
   ],
   "n_groups": 3,
   "ordered": false,
   "assessment": "side by side",
   "resolves_to_finer": false,
   "ev": [
    {
     "loc": "text",
     "q": "46% were Hispanic, 22% were black, and 23% were white; these proportions differ from those among women with reported race/ethnicity who gave birth in 2019"
    }
   ]
  },
  {
   "across": [
    "age"
   ],
   "n_groups": null,
   "ordered": true,
   "assessment": "side by side",
   "resolves_to_finer": false,
   "ev": [
    {
     "loc": "text",
     "q": "When stratified by age, all outcomes (hospitalization, ICU admission, receipt of mechanical ventilation, and death) were more frequently reported among women aged 35–44 years"
    }
   ]
  }
 ],
 "uncertain_fields": [
  "equity.level"
 ],
 "confidence": "high",
 "notes": "Risk ratios are given only for all women; the age and race/ethnicity rows of Table 2 give stratum percentages without stratum-specific ratios. Interaction and sensitivity analysis are not mentioned, so both are null.",
 "view_issues": "Table 2 CSV repeats each outcome's overall crude and adjusted risk ratio in every age and race/ethnicity row (merged cells expanded), and the ICU block lists 'Hispanic or Latino' twice."
}


=== examples/mm7223a3.json ===
{
 "id": "mm7223a3",
 "reader": {
  "model": "claude-opus-5-5",
  "reader_id": "example",
  "role": "example"
 },
 "data_focus": {
  "v": "yes",
  "ev": []
 },
 "outcome_types": [
  {
   "v": "binary/categorical",
   "ev": [
    {
     "loc": "text",
     "q": "an estimated 34.0% of the eligible population had received a first dose of JYNNEOS vaccine by the end of April 2023"
    }
   ]
  }
 ],
 "analytic_depth": [
  {
   "v": "summary",
   "ev": [
    {
     "loc": "summary",
     "q": "As of April 2023, two thirds (approximately 66.0%) of mpox vaccine–eligible persons remained unvaccinated."
    }
   ]
  },
  {
   "v": "comparison",
   "ev": [
    {
     "loc": "text",
     "q": "The first dose coverage shortfall was larger among Black (77.9%) and AI/AN (74.5%) persons than among White (66.6%)"
    }
   ]
  }
 ],
 "procedures": [
  {
   "name": "shortfall analysis (100% minus first-dose coverage)",
   "class": "other",
   "regression_family": null,
   "inferred_from": "\"Shortfall was defined as ...\": a gap from a fixed 100% target, no model or test",
   "role": "primary",
   "ev": [
    {
     "loc": "text",
     "q": "Shortfall was defined as the percentage of the vaccine-eligible population that did not receive the vaccine"
    }
   ]
  },
  {
   "name": "monthly percent reduction in shortfall",
   "class": "other",
   "regression_family": null,
   "inferred_from": "percent decrease from the preceding month's shortfall",
   "role": "primary",
   "ev": [
    {
     "loc": "table 2",
     "q": "Monthly reductions in shortfall were calculated as percent decrease in shortfall compared with the preceding month."
    }
   ]
  },
  {
   "name": "estimation of race-specific eligible-population denominators",
   "class": "other",
   "regression_family": null,
   "inferred_from": "\"race and ethnicity weights\" apportion denominators; this is not survey weighting",
   "role": "ancillary",
   "ev": [
    {
     "loc": "text",
     "q": "The size of the eligible population was calculated as 125% of the sum of the estimated number of MSM with HIV"
    },
    {
     "loc": "note",
     "q": "estimated by multiplying the number of MSM with HIV PrEP indications by the race and ethnicity weights"
    }
   ]
  }
 ],
 "comparison": {
  "framework": "fixed referent",
  "scale": "both",
  "referent": "100% coverage",
  "across": [
   "race/ethnicity",
   "month"
  ],
  "ev": [
   {
    "loc": "text",
    "q": "without the need for a reference group, because the reference point is 100% coverage"
   },
   {
    "loc": "summary",
    "q": "The shortfall (difference between 100% coverage and reported first-dose coverage) was largest among Black or African American (Black) persons (77.9%)."
   }
  ]
 },
 "inference": {
  "v": "none",
  "method_stated": false,
  "ev": []
 },
 "primary_measures": [
  {
   "v": "shortfall, %",
   "ev": [
    {
     "loc": "table 1",
     "q": "Shortfall was calculated by subtracting the cumulative percentage of eligible population that received ≥1 dose of vaccine from 100%."
    }
   ]
  },
  {
   "v": "reduction in shortfall, %",
   "ev": [
    {
     "loc": "table 2",
     "q": "Percent reductions in shortfall in administration of first JYNNEOS vaccine doses among vaccine-eligible persons"
    }
   ]
  },
  {
   "v": "% vaccinated",
   "ev": [
    {
     "loc": "table 1",
     "q": "Cumulative percent vaccinated and shortfalls are rounded to the nearest 10th of a percent."
    }
   ]
  }
 ],
 "regression_fields": null,
 "public_health_question": {
  "v": "Was progress in first-dose mpox vaccination coverage among eligible persons equitable across racial and ethnic groups?",
  "ev": [
   {
    "loc": "text",
    "q": "A shortfall analysis was conducted to examine whether the increase in mpox vaccination coverage was equitable across all racial and ethnic groups"
   }
  ]
 },
 "conditions": [
  {
   "v": "mpox",
   "role": "vaccine target",
   "ev": [
    {
     "loc": "title",
     "q": "Progress Toward Equitable Mpox Vaccination Coverage: A Shortfall Analysis"
    }
   ]
  }
 ],
 "study_design": [
  {
   "v": "surveillance/descriptive",
   "ev": [
    {
     "loc": "text",
     "q": "obtained from case surveillance reports submitted to CDC by 49 states, the District of Columbia, and Puerto Rico"
    }
   ]
  }
 ],
 "data_source_type": [
  {
   "v": "CDC surveillance system",
   "ev": [
    {
     "loc": "text",
     "q": "obtained from case surveillance reports submitted to CDC by 49 states, the District of Columbia, and Puerto Rico"
    },
    {
     "loc": "note",
     "q": "using CDC’s HIV, hepatitis, sexually transmitted infections, and tuberculosis surveillance data"
    }
   ]
  },
  {
   "v": "other",
   "ev": [
    {
     "loc": "note",
     "q": "using 2021 population estimates from CDC wonder"
    }
   ]
  }
 ],
 "data_source_named": [
  {
   "v": "Atlas Plus",
   "ev": [
    {
     "loc": "text",
     "q": "obtained using data from CDC Atlas Plus"
    }
   ]
  },
  {
   "v": "CDC WONDER",
   "ev": [
    {
     "loc": "note",
     "q": "using 2021 population estimates from CDC wonder"
    }
   ]
  }
 ],
 "setting": {
  "v": "US national",
  "ev": [
   {
    "loc": "title",
    "q": "United States, May 2022–April 2023"
   }
  ]
 },
 "vaccine_outcome_type": {
  "v": "coverage/uptake",
  "ev": [
   {
    "loc": "summary",
    "q": "As of April 2023, two thirds (approximately 66.0%) of mpox vaccine–eligible persons remained unvaccinated."
   }
  ]
 },
 "equity": {
  "level": 4,
  "level_reason": "Racial and ethnic shortfalls are framed as disparities, quantified against 100% coverage (Black 77.9%, White 66.6%) and interpreted. Vaccine supply, access initiatives and social determinants of health are named as explanations.",
  "level_confidence": "medium",
  "level_alternative": {
   "level": 3,
   "reason": "Social determinants are named in a limitation as a reason shortfalls may be underestimated, not analysed."
  },
  "dimensions": [
   {
    "v": "race/ethnicity",
    "role": "primary comparison",
    "ev": [
     {
      "loc": "text",
      "q": "Monthly mpox vaccination shortfalls were calculated and were stratified by race and ethnicity"
     }
    ]
   },
   {
    "v": "sexual orientation and gender identity",
    "role": "population",
    "ev": [
     {
      "loc": "text",
      "q": "The size of the eligible population was calculated as 125% of the sum of the estimated number of MSM with HIV"
     }
    ]
   },
   {
    "v": "age",
    "role": "population",
    "ev": [
     {
      "loc": "text",
      "q": "Data on the number of persons aged ≥13 years among seven racial and ethnic groups"
     }
    ]
   }
  ],
  "determinants_of_health": {
   "v": "social determinants of health; vaccine supply; access to vaccination; sexual partnership selection patterns",
   "ev": [
    {
     "loc": "text",
     "q": "because of social determinants of health and sexual partnership selection patterns based on race and ethnicity"
    },
    {
     "loc": "text",
     "q": "which could be related to an increase in vaccine supply resulting from the recommendation for dose-sparing intradermal administration"
    },
    {
     "loc": "text",
     "q": "prioritizing resources and improving access to vaccination for these groups"
    }
   ]
  },
  "equity_action": {
   "v": true,
   "ev": [
    {
     "loc": "text",
     "q": "A shortfall analysis was conducted to examine whether the increase in mpox vaccination coverage was equitable across all racial and ethnic groups"
    }
   ]
  },
  "equity_measurement": "The referent is 100% coverage, not a comparison group. Race-specific denominators assume PrEP indications follow the U.S. male race distribution; recipients missing race/ethnicity (9%) and Vermont are excluded."
 },
 "groupwise": [
  {
   "across": [
    "race/ethnicity"
   ],
   "n_groups": 7,
   "ordered": false,
   "assessment": "side by side",
   "resolves_to_finer": false,
   "ev": [
    {
     "loc": "summary",
     "q": "The shortfall (difference between 100% coverage and reported first-dose coverage) was largest among Black or African American (Black) persons (77.9%)."
    },
    {
     "loc": "text",
     "q": "Data on the number of persons aged ≥13 years among seven racial and ethnic groups"
    }
   ]
  }
 ],
 "uncertain_fields": [
  "equity.level"
 ],
 "confidence": "high",
 "notes": "A supplemental analysis with an alternative race distribution of the eligible population (from new HIV diagnoses) changes group shortfalls (Black 87.8% vs 77.9%); the schema has no sensitivity field outside regression. Rate ratios (1.2, 5.8) are cited from a previous report, and a footnote computes a relative likelihood of eligibility (1.83); both are context, not the main analysis.",
 "view_issues": null
}
